function diferenciaTrasAjuste(estacion, nuevosMinutos) {
  const copia = structuredClone(estacion);
  copia.minutosAlSiguiente = nuevosMinutos;
  return estacion.minutosAlSiguiente - copia.minutosAlSiguiente;
}
